<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??0);$c=srnu_obtener_cotizacion($id);if(!$c){http_response_code(404);exit('Cotización no encontrada');}$pag=srnu_total_pagado($id);if($pag<=0&&!empty($c['conservar_anticipo_recibido']))$pag=(float)$c['anticipo_recibido_monto'];$saldo=max(0,(float)$c['total']-$pag);$s=$pdo->prepare("SELECT COUNT(*) FROM cotizacion_items WHERE cotizacion_id=? AND tipo_entrega='sobre_pedido'");$s->execute([$id]);$sobre=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT COUNT(*) FROM garantias WHERE cotizacion_id=?');$s->execute([$id]);$gar=(int)$s->fetchColumn();$s=$pdo->prepare('SELECT COUNT(*) FROM galeria_trabajos WHERE cotizacion_id=?');$s->execute([$id]);$fotos=(int)$s->fetchColumn();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=eh($c['folio'])?> · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1><?=eh($c['folio'])?></h1><p><?=eh($c['cliente'])?> · <?=eh($c['vehiculo'])?> · <?=eh($c['telefono'])?></p></div><div class="toolbar"><a class="btn light" href="cotizaciones.php">← Cotizaciones</a><a class="btn blue" href="cotizador.php?id=<?=$id?>">Editar cotización</a></div></div><div class="kpi-grid"><div class="kpi"><small>Total</small><strong><?=emoney($c['total'])?></strong></div><div class="kpi"><small>Pagado</small><strong><?=emoney($pag)?></strong></div><div class="kpi"><small>Saldo</small><strong><?=emoney($saldo)?></strong></div><div class="kpi"><small>Estado</small><strong style="font-size:20px"><?=eh($c['estado'])?></strong></div></div><?php if($sobre):?><div class="srnu-security-note" style="margin-top:16px"><b>Sobre pedido:</b>&nbsp; esta cotización contiene <?=$sobre?> concepto(s) que requieren compra/espera de proveedor. <a href="compras.php?cotizacion_id=<?=$id?>">Gestionar pedido</a></div><?php endif;?><div class="grid-3" style="margin-top:16px"><?php $cards=[['pagos.php?id='.$id,'Pagos','Abonos, anticipo y saldo.'],['agenda.php?cotizacion_id='.$id,'Agenda','Programar ingreso y entrega.'],['orden_trabajo.php?id='.$id,'Orden de trabajo','Ejecución, responsables e inventario.'],['recepcion.php?id='.$id,'Recepción','Kilometraje, daños, fotos y firma.'],['firma_digital.php?id='.$id,'Firma cliente','Enviar enlace y consultar la aceptación firmada.'],['firma_taller.php?id='.$id,'Firma taller','Capturar la firma digital de SRNU CUSTOM.'],['confirmacion_local.php?id='.$id,'Confirmación local','Aceptar desde un celular conectado a la misma red Wi‑Fi, sin dibujar firma.'],['expediente.php?id='.$id,'Expediente','Placas, VIN e historial del vehículo.'],['costos.php?id='.$id,'Costos reales','Presupuesto vs costo real y utilidad.'],['reparto.php?id='.$id,'Reparto final','Objetivo, recibido y pendiente por integrante.'],['galeria.php?id='.$id,'Galería','Antes, durante y después.'],['notas.php?id='.$id,'Notas / archivos','Información privada y adjuntos.'],['garantias.php?id='.$id,'Garantías','Garantías activas y vencimientos.'],['versiones.php?id='.$id,'Versiones','Historial y comparación de cambios.'],['ver_pdf.php?id='.$id.'&tipo='.($c['requiere_factura']==='si'?'factura':'sin_factura'),'Ver PDF','Documento final del cliente.']];foreach($cards as $x):?><a class="card" style="text-decoration:none;color:inherit;min-height:120px" href="<?=eh($x[0])?>"><span class="srnu-stat-accent"></span><h2 style="margin:0 0 8px"><?=eh($x[1])?></h2><p class="muted"><?=eh($x[2])?></p></a><?php endforeach;?></div><section class="panel" style="padding:18px;margin-top:16px"><div class="toolbar"><a class="btn green" target="_blank" href="whatsapp.php?id=<?=$id?>">WhatsApp</a><a class="btn light" href="duplicar_cotizacion.php?id=<?=$id?>" onclick="return confirm('¿Duplicar esta cotización?')">Duplicar cotización</a><a class="btn light" href="comparar_versiones.php?id=<?=$id?>">Comparar versiones</a><span class="muted">Garantías: <?=$gar?> · Fotos: <?=$fotos?></span></div></section></main></body></html>
